node --input-type=module <<'NODE'
const f = Math.fround;
const seq = xs => xs.reduce((a,b) => f(a+b), 0);
const block = xs => seq(Array.from({length:Math.ceil(xs.length/4)},(_,b)=>seq(xs.slice(4*b,4*b+4))));
const bits = v => new Uint32Array(Float32Array.of(v).buffer)[0].toString(16);
for (const xs of [[1,0,0,0,2**-24,2**-24,0,0],Array(9).fill(1)]) {
  console.log({serial:seq(xs),serialBits:bits(seq(xs)),blocked:block(xs),blockedBits:bits(block(xs)),reference:xs.reduce((a,b)=>a+b,0),dropTail:block(xs.slice(0,xs.length-xs.length%4))})
}
console.log('nonfused',f(f(4097*4097)-16785408),'fused',f(4097*4097-16785408))
