node --disable-warning=ExperimentalWarning --experimental-transform-types --input-type=module <<'NODE'
import {registerHooks} from 'node:module';
registerHooks({resolve(s,ctx,next){return next(s.startsWith('.') && s.endsWith('.js') ? s.slice(0,-3)+'.ts' : s,ctx)}});
const I = await import('./src/framework/ir/index.ts');
const C = await import('./src/framework/contracts/index.ts');
const P = await import('./src/framework/passes/index.ts');
const {exampleExpression, expressionAdapter, ExpressionIR} = await import('./src/labs/expressions.ts');
const {rebuild, ...readOnly} = expressionAdapter;
const adapter = I.defineAdapter({...readOnly,id:'probe.read-only'});
const r0 = I.createIRArtifact(adapter,'probe',exampleExpression());
C.validateArtifact(ExpressionIR,r0);
const pass = P.definePass({id:'probe.identity',version:'1',description:'identity',ir:ExpressionIR,adapter,writes:{entities:[],relations:[]},run({before}){ console.log('entered native body'); return {native:before.value}; }});
const call = P.applyPass(pass,r0,{manager:new C.AnalysisManager()});
console.log('applyPass Promise',call instanceof Promise);
try {await call} catch(e) {console.log(e.code,e.message)}
const inv = C.differential({id:'probe.eq',version:'1',description:'probe',inputs:{origin:ExpressionIR,candidate:ExpressionIR},baseline:'origin',subject:'candidate',count:1,cases:()=>[0],run:(_,v)=>v.revision,compare:(a,b)=>a===b});
const evidence=C.runDifferential(C.differentialSpec(inv),{origin:r0,candidate:r0});
console.log('synchronous',evidence.method,evidence.status,evidence.agree);
const {immutable} = await import('./src/framework/core/data.ts');
try{immutable(new Float32Array([1]))} catch(e){console.log('typed array',e.message)}
console.log('stored -0 becomes +0',Object.is(immutable({v:-0}).v,0));
