word[0]=0x7fc00000; console.log(Number.isNaN(number[0])); number[0]=Math.fround(-0); console.log(word[0].toString(16));
console.log('affine N+M=7, N-M=1', String((7n+1n)/2n),String((7n-1n)/2n));
